/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(classStr(MultiSelectionHelper))]
internal final class AVAMultiselectionHelper_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_dataSource">_dataSource</param>
/// <returns>boolean</returns>
public static boolean AVAOnlyOneRecordSelected(FormDataSource _dataSource)
{
    if (_dataSource == null)
    {
        throw error("@SYS96323");
    }

    Array recordsMarked = _dataSource.recordsMarked();

    // If there are no records "marked", treat the current record as the only record selected/marked
    if (recordsMarked.lastIndex() == 0)
    {
        return true;
    }



    return false;
}

public static boolean AVAOnlyOneRecordMarked(FormDataSource _dataSource)
{
    if (_dataSource == null)
    {
        throw error("@SYS96323");
    }

    Array recordsMarked = _dataSource.recordsMarked();


    if (recordsMarked.lastIndex() == 1)
    {
        return true;
    }

    return false;
}
